/** Every page in reading order, for previous / next (helpTopics.ts, HELP_ORDER). */
export const HELP_ORDER: readonly HelpTopic[] = HELP_SECTIONS.flatMap((section): readonly HelpTopic[] => section.topics);

/** The section a topic belongs to (helpTopics.ts, sectionOf). */
export const sectionOf = (topic: HelpTopic) =>
  HELP_SECTIONS.find((section) => section.topics.some((id) => id === topic)) ?? HELP_SECTIONS[0];

export function HelpNav({ value }: { value: HelpTopic }) {
  const current = sectionOf(value);
  return (
    <div className="settings-nav-children help-nav" role="group" aria-label="Help topics">
      {HELP_SECTIONS.map((section) => {
        const here = section.id === current.id;
        return (
          <div className="help-nav-section" key={section.id}>
            <button type="button" className={`settings-hub-sublink help-nav-head ${here ? "is-current" : ""}`} aria-expanded={here}>
              <ChevronRight size={12} className="help-nav-chevron" aria-hidden="true" />
              <span className="settings-hub-sublabel">{section.label}</span>
            </button>
            {here ? (
              <div className="help-nav-pages" role="group" aria-label={`${section.label} pages`}>
                {section.topics.map((topic) => {
                  const label = HELP_LABELS[topic];
                  const active = topic === value;
                  return (
                    <button
                      type="button"
                      key={topic}
                      title={label}
                      aria-current={active ? "page" : undefined}
                      className={`settings-hub-sublink help-nav-page ${active ? "active" : ""}`}
                    >
                      <span className="settings-hub-sublabel">{label}</span>
                    </button>
                  );
                })}
              </div>
            ) : null}
          </div>
        );
      })}
    </div>
  );
}
